    (client_id, customer_unique_id, ville, etat, code_postal_prefixe,
     valide_du, valide_au, est_courante)
VALUES (0, 'inconnu', 'inconnu', 'inconnu', 'inconnu', '1900-01-01', NULL, TRUE)
ON CONFLICT (client_id) DO NOTHING;

