     rattache, langue, valide_du, valide_au, est_courante)
VALUES (0, 'inconnu', 'inconnu', 'inconnu', NULL, FALSE, NULL, '1900-01-01', NULL, TRUE)
ON CONFLICT (produit_id) DO NOTHING;

